  @JvmStatic fun cbrt(x: Double): Double = if (x != x) R.quiet(x) else cbrt_t(x)
  @JvmStatic fun cosh(x: Double): Double = if (x != x) R.quiet(x) else cosh_t(x)
  @JvmStatic fun sinh(x: Double): Double = if (x != x) R.quiet(x) else sinh_t(x)
  @JvmStatic fun tanh(x: Double): Double = if (x != x) R.quiet(x) else tanh_t(x)
  @JvmStatic fun log2(x: Double): Double = if (x != x) R.quiet(x) else log2_t(x)
  @JvmStatic fun expm1(x: Double): Double = if (x != x) R.quiet(x) else expm1_t(x)
  @JvmStatic fun log1p(x: Double): Double = if (x != x) R.quiet(x) else log1p_t(x)
  @JvmStatic fun hypot(x: Double, y: Double): Double = if (x != x && y != y) R.quiet(x) else hypot_t(x, y)
  @JvmStatic fun atan2(y: Double, x: Double): Double {
    if (x != x) return R.quiet(x)
    if (y != y) return R.quiet(y)
    return atan2_t(y, x)
  }
}
